MakeTube(ModeInfo *mi, int direction)
{
    Bool        wire = MI_IS_WIREFRAME(mi);
	float       an;
	float       SINan_3, COSan_3;
    int facets = (wire ? 5 : 24);

	/*dirUP    = 00000000 */
