/* With a 90 degree field of view and the eye at z 5, x = 2.5 at z 0 lands at
 * ndc 0.5, which is pixel column 48 of 64. Red, not white, so a byte swap
 * would show. */
void test_perspective_and_lookat_put_a_point_where_the_maths_says(void) {
  TEST_ASSERT_NOT_NULL(glshim_open(&cv));
  glViewport(0, 0, SIZE, SIZE);
  glMatrixMode(GL_PROJECTION);
  glLoadIdentity();
  gluPerspective(90, 1, 1, 100);
  glMatrixMode(GL_MODELVIEW);
  glLoadIdentity();
  gluLookAt(0, 0, 5, 0, 0, 0, 0, 1, 0);
  glDisable(GL_LIGHTING);
  glColor3f(1, 0, 0);
  glBegin(GL_TRIANGLES);
  glVertex3f(2.0f, -1.0f, 0.0f);
  glVertex3f(3.0f, -1.0f, 0.0f);
  glVertex3f(2.5f, 1.0f, 0.0f);
  glEnd();
  TEST_ASSERT_EQUAL_HEX16(rgb565(255, 0, 0), cv.px[32 * SIZE + 48]);
  TEST_ASSERT_EQUAL_HEX16(0, cv.px[32 * SIZE + 16]);
}

