#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"

static Canvas cv;
void setUp(void) { canvas_init(&cv, 466, 466, malloc); }
void tearDown(void) { canvas_free(&cv); }

static long B(void) { return (long)__sanitizer_get_current_allocated_bytes(); }

void test_probe(void) {
  int gears = -1;
  for (int i = 0; i < g_hack_count; i++)
    if (strcmp(g_hacks[i]->name, "Gears") == 0) gears = i;
  TEST_ASSERT_TRUE(gears >= 0);
  char msg[600];
  int n = 0;
  srandom(1);
  for (int cycle = 0; cycle < 5; cycle++) {
    long a = B();
    HackRunner *r = runner_create(&cv);
    long b = B();
    runner_start(r, gears);
    long c = B();
    for (int f = 0; f < 5; f++) runner_step(r);
    long d = B();
    runner_destroy(r);
    long e = B();
    n += snprintf(msg + n, sizeof msg - n,
