 * release hook when the hack stops. Without it every visit to Gears would
 * leave that behind. Growth over 40 restarts is exactly 0, so 512 bytes is
 * slack. */
void test_gears_start_and_stop_do_not_leak(void) {
  const int gears = index_of("Gears");
  TEST_ASSERT_TRUE(gears >= 0);
  srandom(1);
  HackRunner *r = runner_create(&cv);
  for (int i = 0; i < 3; i++) {
    runner_start(r, gears);
    runner_step(r);
  }
  const size_t before = __sanitizer_get_current_allocated_bytes();
  for (int i = 0; i < 40; i++) {
    runner_start(r, gears);
    runner_step(r);
  }
  const size_t after = __sanitizer_get_current_allocated_bytes();
  runner_destroy(r);
  TEST_ASSERT_EQUAL_UINT64(before, after); /* TEMP */
  TEST_ASSERT_TRUE_MESSAGE(after < before + 512, "allocated bytes grew");
}

/* Gears builds its gears with involute.c at start-up and draws from display
 * lists after that, so its stack use is shallow; this proves it stays under
 * the loop task's 16 KB (AddressSanitizer inflates the frames here, so under
 * it here means under it there). Three seeds give different layouts. */
void test_gears_stays_within_the_loop_task_stack(void) {
  const int gears = index_of("Gears");
  TEST_ASSERT_TRUE(gears >= 0);
  long worst = 0;
  for (int seed = 1; seed <= 3; seed++) {
