/* The GL a hack sees when it is built with USE_GL: TinyGL's API, the entry
 * points TinyGL defines but its header does not declare, and small stand-ins
 * for the GLU and GLX calls hacks make. Not derived from xscreensaver code. */
#ifndef GLSHIM_H
#define GLSHIM_H

#include "GL/gl.h"
#include "x11shim/xshim.h"

#ifdef __cplusplus
extern "C" {
#endif

/* There is one context and one drawable, so GLX has little to do. */
typedef void *GLXContext;
typedef Drawable GLXDrawable;

/* Opens TinyGL over the canvas's pixels, replacing any open context, and
 * registers a hook so the context is freed when the hack stops. Returns a
 * handle for the hack to keep, or NULL if the canvas is empty or TinyGL cannot
 * allocate its z-buffer. */
GLXContext *glshim_open(Canvas *canvas);
/* Frees the context. Safe to call when none is open. */
void glshim_close(void);

Bool glXMakeCurrent(Display *dpy, GLXDrawable drawable, GLXContext ctx);
/* TinyGL has drawn into the canvas already; this marks all of it dirty. */
void glXSwapBuffers(Display *dpy, GLXDrawable drawable);

void gluPerspective(GLdouble fovy, GLdouble aspect, GLdouble znear,
                    GLdouble zfar);
void gluLookAt(GLdouble eyex, GLdouble eyey, GLdouble eyez, GLdouble cx,
               GLdouble cy, GLdouble cz, GLdouble upx, GLdouble upy,
               GLdouble upz);

/* TinyGL counts a vertex array's stride in floats and reads the array when a
 * display list is replayed. GL counts bytes and reads at the draw call, and
 * hacks free an array straight after drawing it. So hacks' array calls come
 * here, and a draw is expanded at once into glBegin, glNormal3f, glVertex3f
 * and glEnd. A stride of 0 means tightly packed. Texture coordinates are
 * accepted and ignored. */
void glshim_VertexPointer(GLint size, GLenum type, GLsizei stride,
                          const GLvoid *pointer);
void glshim_NormalPointer(GLenum type, GLsizei stride, const GLvoid *pointer);
void glshim_ColorPointer(GLint size, GLenum type, GLsizei stride,
                         const GLvoid *pointer);
void glshim_TexCoordPointer(GLint size, GLenum type, GLsizei stride,
                            const GLvoid *pointer);
void glshim_EnableClientState(GLenum array);
void glshim_DisableClientState(GLenum array);
void glshim_DrawArrays(GLenum mode, GLint first, GLsizei count);
#define glVertexPointer glshim_VertexPointer
#define glNormalPointer glshim_NormalPointer
#define glColorPointer glshim_ColorPointer
#define glTexCoordPointer glshim_TexCoordPointer
#define glEnableClientState glshim_EnableClientState
#define glDisableClientState glshim_DisableClientState
#define glDrawArrays glshim_DrawArrays

void glMateriali(GLint face, GLint pname, GLint value);
/* The only caller asks about GL_TEXTURE_2D, which no hack here enables. */
int glIsEnabled(GLint cap);

/* TinyGL defines these but its header does not declare them. */
void glVertex3f(GLfloat x, GLfloat y, GLfloat z);
void glNormal3f(GLfloat x, GLfloat y, GLfloat z);
void glColor3f(GLfloat r, GLfloat g, GLfloat b);
void glColor4f(GLfloat r, GLfloat g, GLfloat b, GLfloat a);

#ifdef __cplusplus
}
#endif

#endif

/* The GL context layer. TinyGL draws straight into the canvas, so a "swap"
 * only has to mark the canvas dirty. Not derived from xscreensaver code. */
#include "glshim/glshim.h"

#include <math.h>

#include "core/canvas.h"
#include "zbuffer.h"

static ZBuffer *g_zb;
static Canvas *g_canvas;

static void release_hook(Display *dpy) {
  (void)dpy;
  glshim_close();
}

void glshim_close(void) {
  if (!g_zb) return;
  glClose();
  ZB_close(g_zb);
  g_zb = NULL;
  g_canvas = NULL;
}

GLXContext *glshim_open(Canvas *canvas) {
  static GLXContext handle;

  glshim_close();
  if (!canvas || !canvas->px || canvas->w <= 0 || canvas->h <= 0) return NULL;
  g_zb = ZB_open(canvas->w, canvas->h, ZB_MODE_5R6G5B, canvas->px);
  if (!g_zb) return NULL;
  glInit(g_zb);
  g_canvas = canvas;
  xshim_set_release_hook(release_hook);
  handle = g_zb;
  return &handle;
}

Bool glXMakeCurrent(Display *dpy, GLXDrawable drawable, GLXContext ctx) {
  (void)dpy;
  (void)drawable;
  (void)ctx;
  return 1;
}

void glXSwapBuffers(Display *dpy, GLXDrawable drawable) {
  (void)dpy;
  (void)drawable;
  if (g_canvas) canvas_mark_dirty(g_canvas, 0, 0, g_canvas->w, g_canvas->h);
}

typedef struct {
  const char *data;
  int size;
  int stride; /* bytes between elements */
  int on;
} ClientArray;

static ClientArray g_vertex, g_normal, g_color;

static int stride_in_bytes(int stride, int size) {
  return stride ? stride : size * (int)sizeof(GLfloat);
}

void glshim_VertexPointer(GLint size, GLenum type, GLsizei stride,
                          const GLvoid *pointer) {
  (void)type;
  g_vertex.data = pointer;
  g_vertex.size = size;
  g_vertex.stride = stride_in_bytes(stride, size);
}

void glshim_NormalPointer(GLenum type, GLsizei stride, const GLvoid *pointer) {
  (void)type;
  g_normal.data = pointer;
  g_normal.size = 3;
  g_normal.stride = stride_in_bytes(stride, 3);
}

void glshim_ColorPointer(GLint size, GLenum type, GLsizei stride,
                         const GLvoid *pointer) {
  (void)type;
  g_color.data = pointer;
  g_color.size = size;
  g_color.stride = stride_in_bytes(stride, size);
}

void glshim_TexCoordPointer(GLint size, GLenum type, GLsizei stride,
                            const GLvoid *pointer) {
  (void)size;
  (void)type;
  (void)stride;
  (void)pointer;
}

static ClientArray *client_array(GLenum array) {
  switch (array) {
    case GL_VERTEX_ARRAY:
      return &g_vertex;
    case GL_NORMAL_ARRAY:
      return &g_normal;
    case GL_COLOR_ARRAY:
      return &g_color;
    default:
      return NULL;
  }
}

void glshim_EnableClientState(GLenum array) {
  ClientArray *a = client_array(array);
  if (a) a->on = 1;
}

void glshim_DisableClientState(GLenum array) {
  ClientArray *a = client_array(array);
  if (a) a->on = 0;
}

static const GLfloat *element(const ClientArray *a, GLint i) {
  return (const GLfloat *)(a->data + (size_t)i * (size_t)a->stride);
}

void glshim_DrawArrays(GLenum mode, GLint first, GLsizei count) {
  glBegin(mode);
  for (GLint i = first; i < first + count; i++) {
    if (g_color.on) {
      const GLfloat *c = element(&g_color, i);
      glColor4f(c[0], c[1], c[2], g_color.size > 3 ? c[3] : 1.0f);
    }
    if (g_normal.on) {
      const GLfloat *n = element(&g_normal, i);
      glNormal3f(n[0], n[1], n[2]);
    }
    if (g_vertex.on) {
      const GLfloat *v = element(&g_vertex, i);
      glVertex3f(v[0], v[1], g_vertex.size > 2 ? v[2] : 0.0f);
    }
  }
  glEnd();
}

void glMateriali(GLint face, GLint pname, GLint value) {
  GLfloat v[4] = {(GLfloat)value, 0, 0, 1};
  glMaterialfv(face, pname, v);
}

int glIsEnabled(GLint cap) {
  (void)cap;
  return 0;
}

void gluPerspective(GLdouble fovy, GLdouble aspect, GLdouble znear,
                    GLdouble zfar) {
  const float top = (float)znear * tanf((float)fovy * 3.14159265f / 360.0f);
  const float right = top * (float)aspect;
  glFrustum(-right, right, -top, top, znear, zfar);
}

static void normalize3(float v[3]) {
  const float len = sqrtf(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
  if (len > 0) {
    v[0] /= len;
    v[1] /= len;
    v[2] /= len;
  }
}

static void cross3(const float a[3], const float b[3], float out[3]) {
  out[0] = a[1] * b[2] - a[2] * b[1];
  out[1] = a[2] * b[0] - a[0] * b[2];
  out[2] = a[0] * b[1] - a[1] * b[0];
}

void gluLookAt(GLdouble eyex, GLdouble eyey, GLdouble eyez, GLdouble cx,
               GLdouble cy, GLdouble cz, GLdouble upx, GLdouble upy,
               GLdouble upz) {
  float f[3] = {(float)(cx - eyex), (float)(cy - eyey), (float)(cz - eyez)};
  const float up[3] = {(float)upx, (float)upy, (float)upz};
  float s[3], u[3];
  normalize3(f);
  cross3(f, up, s);
  normalize3(s);
  cross3(s, f, u);
  /* Column-major, as glMultMatrixf takes it. */
  GLfloat m[16] = {s[0], u[0], -f[0], 0, s[1], u[1], -f[1], 0,
                   s[2], u[2], -f[2], 0, 0,    0,    0,     1};
  glMultMatrixf(m);
  glTranslatef((GLfloat)-eyex, (GLfloat)-eyey, (GLfloat)-eyez);
}

